INSERT INTO `facts` VALUES (1834,'sr','遗器套装','泛银河商业公司','名称','泛银河商业公司',NULL,1275,'https://wiki.biligame.com/sr/泛银河商业公司','2026-09-10T19:59:15Z',NULL),(1835,'sr','遗器套装','泛银河商业公司','类别','位面饰品',NULL,1275,'https://wiki.biligame.com/sr/泛银河商业公司','2026-09-10T19:59:15Z',NULL),(1836,'sr','遗器套装','泛银河商业公司','两件套效果','使装备者的效果命中提高10%，同时提高装备者等同于当前效果命中25%的攻击力，最多提高25%。',NULL,1275,'https://wiki.biligame.com/sr/泛银河商业公司','2026-09-10T19:59:15Z',NULL),(1837,'sr','遗器套装','泛银河商业公司','获取方式','模拟宇宙、差分宇宙',NULL,1275,'https://wiki.biligame.com/sr/泛银河商业公司','2026-09-10T19:59:15Z',NULL),(1838,'sr','遗器套装','泛银河商业公司','获取途径','模拟宇宙•第五世界、差分宇宙',NULL,1275,'https://wiki.biligame.com/sr/泛银河商业公司','2026-09-10T19:59:15Z',NULL),(1839,'sr','遗器套装','泛银河商业公司','实装版本','1.0',1,1275,'https://wiki.biligame.com/sr/泛银河商业公司','2026-09-10T19:59:15Z',NULL),(1840,'sr','遗器套装','泛银河商业公司','TAG','效果命中、攻击力',NULL,1275,'https://wiki.biligame.com/sr/泛银河商业公司','2026-09-10T19:59:15Z',NULL),(1841,'sr','遗器套装','泛银河商业公司','相关角色','托帕&账账、砂金、翡翠、真珠',NULL,1275,'https://wiki.biligame.com/sr/泛银河商业公司','2026-09-10T19:59:15Z',NULL),(1842,'sr','遗器套装','泛银河商业公司','位面球','公司的巨构总部',NULL,1275,'https://wiki.biligame.com/sr/泛银河商业公司','2026-09-10T19:59:15Z',NULL),(1843,'sr','遗器套装','泛银河商业公司','连结绳','公司的贸易航道',NULL,1275,'https://wiki.biligame.com/sr/泛银河商业公司','2026-09-10T19:59:15Z',NULL),(1844,'sr','遗器套装','泛银河商业公司','位面球描述','位于庇尔波因特的公司总部被封存在位面球中。在星际和平公司的商业宏图之中，没有一颗星球可以置身事外，他们前往深空，是为了将全宇宙的力量集合起来。',NULL,1275,'https://wiki.biligame.com/sr/泛银河商业公司','2026-09-10T19:59:15Z',NULL),(1845,'sr','遗器套装','泛银河商业公司','连结绳描述','借助「信用点体系」的便利，跨越星际的商贸得以成立。星际和平公司用经济活动连缀繁星，拓展了贸易边界。',NULL,1275,'https://wiki.biligame.com/sr/泛银河商业公司','2026-09-10T19:59:15Z',NULL),(1846,'sr','遗器套装','星体差分机','名称','星体差分机',NULL,1484,'https://wiki.biligame.com/sr/星体差分机','2025-04-13T06:13:49Z',NULL),(1847,'sr','遗器套装','星体差分机','类别','位面饰品',NULL,1484,'https://wiki.biligame.com/sr/星体差分机','2025-04-13T06:13:49Z',NULL),(1848,'sr','遗器套装','星体差分机','两件套效果','使装备者的暴击伤害提高16%。当装备者的暴击伤害大于等于120%时，进入战斗后装备者的暴击率提高60%，持续到施放首次攻击后结束。',NULL,1484,'https: