  `page_id` bigint NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `url` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL,
  `last_revision` bigint NOT NULL,
  `last_revision_ts` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `infobox` json DEFAULT NULL,
  `n_chars` int NOT NULL,
  `n_chunks` int NOT NULL,
  `fetched_at` datetime NOT NULL,
  `content_hash` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pages_game_pageid` (`game`,`page_id`),
  KEY `ix_pages_game` (`game`),
  KEY `ix_pages_game_title` (`game`,`title`),
  KEY `ix_pages_content_hash` (`content_hash`)
) ENGINE=InnoDB AUTO_INCREMENT=14938 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
